// Derives every additive DDL statement the app uses from prisma/schema.prisma, so
// the Prisma schema stays the only place a table, column or index is declared.
//
//   node scripts/generate-schema-sql.mjs          rewrite the generated files
//   node scripts/generate-schema-sql.mjs --check  exit 1 when they are stale
//
// Outputs:
//   app/services/schemaStatements.generated.js       runtime repair + build preparation
//   prisma/migrations/00000000000000_baseline/...    lets `prisma migrate deploy` build an empty database
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const MODULE_PATH = path.join(ROOT, "app/services/schemaStatements.generated.js");
const BASELINE_PATH = path.join(ROOT, "prisma/migrations/00000000000000_baseline/migration.sql");
const HEADER = "Generated by scripts/generate-schema-sql.mjs from prisma/schema.prisma. Do not edit by hand.";

function readPrismaSql() {
  return execFileSync(
    process.execPath,
    [
      path.join(ROOT, "node_modules/prisma/build/index.js"),
      "migrate", "diff", "--from-empty", "--to-schema-datamodel", path.join(ROOT, "prisma/schema.prisma"), "--script",
    ],
    {
      cwd: ROOT,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      // The diff never connects; the URL only has to satisfy schema validation.
      env: { ...process.env, PRISMA_DATABASE_URL: process.env.PRISMA_DATABASE_URL || "postgresql://schema:schema@127.0.0.1:1/schema" },
    },
  );
}

// A column added to a table that already holds rows cannot be NOT NULL without a default.
function addableColumnDefinition(definition) {
  if (/\bDEFAULT\b/.test(definition) || !/\bNOT NULL\b/.test(definition)) return definition;
  if (/^TIMESTAMP/.test(definition)) return `${definition} DEFAULT CURRENT_TIMESTAMP`;
  return definition.replace(/\s*\bNOT NULL\b/, "");
}

export function buildStatements(prismaSql) {
  const foreignKeys = new Map();
  for (const [, table, name, body] of prismaSql.matchAll(/^ALTER TABLE "(\w+)" ADD CONSTRAINT "(\w+)" (FOREIGN KEY .+);$/gm)) {
    foreignKeys.set(table, [...(foreignKeys.get(table) || []), `CONSTRAINT "${name}" ${body}`]);
  }
  const indexes = new Map();
  for (const [, unique, name, table, columns] of prismaSql.matchAll(/^CREATE (UNIQUE )?INDEX "(\w+)" ON "(\w+)"\((.+)\);$/gm)) {
    indexes.set(table, [...(indexes.get(table) || []), { name, sql: `CREATE ${unique || ""}INDEX IF NOT EXISTS "${name}" ON "${table}"(${columns})` }]);
  }

  const statements = [];
  for (const [, table, body] of prismaSql.matchAll(/^CREATE TABLE "(\w+)" \(\n([\s\S]*?)\n\);$/gm)) {
    const lines = body.split("\n").map((line) => line.trim().replace(/,$/, "")).filter(Boolean);
    const constraints = lines.filter((line) => line.startsWith("CONSTRAINT"));
    const columns = lines.filter((line) => !line.startsWith("CONSTRAINT")).map((line) => {
      const match = /^"(\w+)" (.+)$/.exec(line);
      if (!match) throw new Error(`Unrecognised column line in ${table}: ${line}`);
      return { name: match[1], definition: match[2] };
    });
    const primaryKey = new Set(
      constraints.flatMap((line) => [...(/PRIMARY KEY \((.+)\)/.exec(line)?.[1] || "").matchAll(/"(\w+)"/g)].map((m) => m[1])),
    );
    if (!columns.length || !primaryKey.size) throw new Error(`Table ${table} has no columns or primary key`);

    const tableLines = [
      ...columns.map((column) => `"${column.name}" ${column.definition}`),
      ...constraints,
      // Inline so a constraint is only ever created together with a brand-new table.
      ...(foreignKeys.get(table) || []),
    ];
    statements.push({ kind: "table", table, name: table, sql: `CREATE TABLE IF NOT EXISTS "${table}" (\n  ${tableLines.join(",\n  ")}\n)` });
    for (const column of columns) {
      // Primary key columns always arrive with the table itself.
      if (primaryKey.has(column.name)) continue;
      statements.push({ kind: "column", table, name: column.name, sql: `ALTER TABLE "${table}" ADD COLUMN IF NOT EXISTS "${column.name}" ${addableColumnDefinition(column.definition)}` });
    }
    for (const index of indexes.get(table) || []) statements.push({ kind: "index", table, name: index.name, sql: index.sql });
  }
  if (!statements.length) throw new Error("Prisma produced no tables");
  return statements;
}

function render(statements) {
  const moduleSource = [
    `// ${HEADER}`,
    "// Every statement is additive and idempotent: nothing here drops, rewrites or deletes.",
    "export const schemaStatements = [",
    ...statements.map((statement) => `  ${JSON.stringify(statement)},`),
    "];",
    "",
  ].join("\n");
  const baseline = [
    `-- ${HEADER}`,
    "-- Idempotent baseline: creates the full schema on an empty database and is a no-op on an existing one.",
    "",
    ...statements.map((statement) => `${statement.sql};\n`),
  ].join("\n");
  return { moduleSource, baseline };
}

function main() {
  const { moduleSource, baseline } = render(buildStatements(readPrismaSql()));
  const targets = [[MODULE_PATH, moduleSource], [BASELINE_PATH, baseline]];
  if (process.argv.includes("--check")) {
    const stale = targets.filter(([file, content]) => !fs.existsSync(file) || fs.readFileSync(file, "utf8") !== content);
    if (stale.length) {
      console.error(`Stale generated schema files:\n${stale.map(([file]) => `  ${path.relative(ROOT, file)}`).join("\n")}\nRun: npm run schema:generate`);
      process.exit(1);
    }
    return;
  }
  for (const [file, content] of targets) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, "utf8");
    console.log(`Wrote ${path.relative(ROOT, file)}`);
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
